      </div>

      {/* HERO PROFILE SUMMARY CARD */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-slate-900 via-blue-950 to-slate-900 text-white p-6 sm:p-8 shadow-xl border border-slate-800">
        <div className="absolute -top-24 -right-24 w-80 h-80 bg-blue-500/20 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -left-24 w-80 h-80 bg-indigo-500/15 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col sm:flex-row items-center sm:items-start gap-6 text-center sm:text-left">
          {/* Avatar Ring */}
          <div className="relative flex-shrink-0 group">
            <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-full ring-4 ring-blue-500/30 bg-gradient-to-tr from-blue-600 to-cyan-400 p-1 shadow-2xl overflow-hidden relative">
              {currentAvatar && !avatarLoadError ? (
                <img
                  src={getImageUrl(currentAvatar)}
