                <div className="p-4 rounded-2xl bg-slate-50/80 border border-slate-100 flex items-center gap-4">
                  <div className="w-14 h-14 rounded-full ring-2 ring-blue-100 bg-blue-900 text-white flex items-center justify-center font-bold text-lg overflow-hidden shadow-sm flex-shrink-0">
                    {profileData.avatar_url && !avatarLoadError ? (
                      <img
                        src={getImageUrl(profileData.avatar_url)}
